// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// LoginAdmin 管理员端登录（手机号 + 密码）
	// (POST /api/v1/auth/admin/login)
	LoginAdmin(ctx context.Context, request LoginAdminRequestObject) (LoginAdminResponseObject, error)
	// Logout 登出
	// (POST /api/v1/auth/logout)
	Logout(ctx context.Context, request LogoutRequestObject) (LogoutResponseObject, error)
	// LoginMerchant 商户端登录（手机号 + 密码）
	// (POST /api/v1/auth/merchant/login)
	LoginMerchant(ctx context.Context, request LoginMerchantRequestObject) (LoginMerchantResponseObject, error)
	// RefreshToken 刷新令牌
	// (POST /api/v1/auth/refresh)
	RefreshToken(ctx context.Context, request RefreshTokenRequestObject) (RefreshTokenResponseObject, error)
	// LoginWechat 微信一键登录
	// (POST /api/v1/auth/wechat/login)
	LoginWechat(ctx context.Context, request LoginWechatRequestObject) (LoginWechatResponseObject, error)
	// GetCart 获取购物车
	// (GET /api/v1/cart)
	GetCart(ctx context.Context, request GetCartRequestObject) (GetCartResponseObject, error)
	// DeleteCartItem 移出购物车
	// (DELETE /api/v1/cart/items/{skuId})
	DeleteCartItem(ctx context.Context, request DeleteCartItemRequestObject) (DeleteCartItemResponseObject, error)
	// PutCartItem 加购 / 改数量（upsert）
	// (PUT /api/v1/cart/items/{skuId})
	PutCartItem(ctx context.Context, request PutCartItemRequestObject) (PutCartItemResponseObject, error)
	// GetMe 当前登录用户
	// (GET /api/v1/me)
	GetMe(ctx context.Context, request GetMeRequestObject) (GetMeResponseObject, error)
	// ListOrders 我的订单列表
	// (GET /api/v1/orders)
	ListOrders(ctx context.Context, request ListOrdersRequestObject) (ListOrdersResponseObject, error)
	// CreateOrder 下单
	// (POST /api/v1/orders)
	CreateOrder(ctx context.Context, request CreateOrderRequestObject) (CreateOrderResponseObject, error)
	// GetOrder 订单详情
	// (GET /api/v1/orders/{orderId})
	GetOrder(ctx context.Context, request GetOrderRequestObject) (GetOrderResponseObject, error)
	// PrepayOrder 发起支付（预下单）
	// (POST /api/v1/orders/{orderId}/pay)
	PrepayOrder(ctx context.Context, request PrepayOrderRequestObject) (PrepayOrderResponseObject, error)
	// MockPayNotify 手动触发一笔 mock 支付成功回调
	// (POST /api/v1/pay/mock/notify)
	MockPayNotify(ctx context.Context, request MockPayNotifyRequestObject) (MockPayNotifyResponseObject, error)
	// ListProducts 商品列表（支持搜索与分页）
	// (GET /api/v1/products)
	ListProducts(ctx context.Context, request ListProductsRequestObject) (ListProductsResponseObject, error)
	// GetProduct 商品详情（含 SKU）
	// (GET /api/v1/products/{productId})
	GetProduct(ctx context.Context, request GetProductRequestObject) (GetProductResponseObject, error)
	// Healthz 存活探针
	// (GET /healthz)
	Healthz(ctx context.Context, request HealthzRequestObject) (HealthzResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

